const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
function distFiles() {
  const dist = path.join(root, "dist");
  return fs.readdirSync(dist).filter((f) => f.endsWith(".js")).map((f) => ({ file: f, src: fs.readFileSync(path.join(dist, f), "utf8") }));
}
let found = null;
for (const f of distFiles()) {
  const m = /var Agent = class Agent extends (\w+) \{/.exec(f.src);
  if (m) {
    found = { file: f.file, base: m[1], src: f.src };
    break;
  }
}
if (!found) {
  console.error("FAIL: could not find the Agent class in agents " + pkg.version);
  process.exit(1);
}
const fromWorkers = /import \{[^}]*\bDurableObject\b[^}]*\} from "cloudflare:workers";/.test(found.src);
const partyserver = Object.keys(pkg.dependencies || {}).includes("partyserver");
if (found.base !== "DurableObject" || !fromWorkers || partyserver) {
  console.error("FAIL: Agent extends " + found.base + " (partyserver dependency: " + partyserver + "), not Cloudflare's DurableObject");
  process.exit(1);
}
console.log("OK: agents " + pkg.version + " Agent extends DurableObject from cloudflare:workers (" + found.file + "); partyserver is not a dependency");

